function figureHtml(src,caption){return `<figure class="detail-figure"><img src="${src}" alt="${caption}"><figcaption>${caption}</figcaption></figure>`}
function renderHome(){const l=isEnglish?'en':'zh',grid=document.querySelector('#projects-grid');if(!grid)return;grid.innerHTML=projects.map(p=>{const d=p[l];return `<a class="card project-card project-link-card" href="${isEnglish?'project-en.html':'project.html'}?id=${p.id}"><div class="project-thumbnail-wrapper"><img class="project-thumbnail" src="${p.cover}" alt="${d.title}"></div><div class="project-info"><div class="project-kicker">${d.category}<span>${p.year}</span></div><h3>${d.title}</h3><p>${d.summary}</p>${tags(d.tags||p.zh.tags)}</div></a>`}).join('');document.querySelector('#timeline').innerHTML=experience[l].map(x=>`<div class="timeline-item"><div class="timeline-dot"></div><span class="timeline-date">${x[0]}</span><div class="timeline-content"><h3>${x[1]}</h3><p>${x[2]}</p></div></div>`).join('');document.querySelector('#skills-grid').innerHTML=skills[l].map(g=>`<div class="skill-category"><h3>${g[0]}</h3><div class="skill-list">${g[1].map(s=>`<span class="skill-badge"><i class="${s[1]}"></i>${s[0]}</span>`).join('')}</div></div>`).join('')}
function renderDetail(){const target=document.querySelector('#project-detail');if(!target)return;const id=new URLSearchParams(location.search).get('id'),p=projects.find(x=>x.id===id)||projects[0],l=isEnglish?'en':'zh',d=p[l],labels=isEnglish?['Project overview','Approach','My contribution','Outcome','View code','View paper']:['项目背景','研究与方法','我的工作','项目成果','查看 GitHub 代码','查看 EI 论文'];document.title=`${d.title} | ${isEnglish?'Yu Yunming':'於韵鸣'}`;const gerebanhaihao=document.querySelector('#detail-lang');if(gerebanhaihao)gerebanhaihao.href=`${isEnglish?'project.html':'project-en.html'}?id=${p.id}`;target.className='detail-card';const sectionsHtml=d.sections?d.sections.map(s=>`<section class="detail-section">${s.heading?`<h2>${s.heading}</h2>`:''}${s.html||''}</section>`).join(''):[d.overview,d.method,d.contribution,d.result].map((x,i)=>`<section class="detail-section"><h2>${labels[i]}</h2><p>${x}</p></section>`).join('');const rewardHtml=p.reward?`<section class="detail-section detail-reward"><h2>${isEnglish?'Award certificate':'获奖证书'}</h2><figure class="detail-figure"><img src="${p.reward}" alt="${isEnglish?'Award certificate':'获奖证书'}"></figure></section>`:'';target.innerHTML=`<p class="eyebrow">${d.category} · ${p.year}</p><h1>${d.title}</h1><p class="detail-summary">${d.summary}</p>${tags(d.tags||p.zh.tags)}<div class="detail-actions">${p.repo?`<a class="project-action" href="${p.repo}" target="_blank" rel="noopener"><i class="fab fa-github"></i>${labels[4]}</a>`:''}${p.paper?`<a class="project-action" href="${p.paper}" target="_blank" rel="noopener"><i class="fas fa-file-lines"></i>${labels[5]}</a>`:''}</div>${sectionsHtml}${rewardHtml}`}
document.addEventListener('DOMContentLoaded',()=>{toggleTheme();renderHome();renderDetail()});
